class Solution {
  public int minArraySum(int[] nums, int k, int op1, int op2) {
    int INF = Integer.MAX_VALUE / 2;
    int[][] dp = new int[op1 + 1][op2 + 1];
    for (int[] row : dp) java.util.Arrays.fill(row, INF);
    dp[0][0] = 0;
    for (int x : nums) {
      int half = (x + 1) / 2, sub = x >= k ? x - k : INF, both = INF;
      if (x >= k) both = Math.min(both, (x - k + 1) / 2);
      if (half >= k) both = Math.min(both, half - k);
      for (int a = op1; a >= 0; a--) {
        for (int b = op2; b >= 0; b--) {
          int v = dp[a][b] + x;
          if (a > 0) v = Math.min(v, dp[a - 1][b] + half);
          if (b > 0 && sub < INF) v = Math.min(v, dp[a][b - 1] + sub);
          if (a > 0 && b > 0 && both < INF) v = Math.min(v, dp[a - 1][b - 1] + both);
          dp[a][b] = Math.min(v, INF);
        }
      }
    }
    int ans = INF;
    for (int[] row : dp) for (int v : row) ans = Math.min(ans, v);
    return ans;
  }
}
